fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let sd: i32 = host::display::state_get(7);
        let mut i: i32 = 0;
        while i < 8 {
            host::display::state_set(20 + i, i / 2);
            host::display::state_set(30 + i, 0);
            i = i + 1;
        }
        let mut j: i32 = 7;
        while j > 0 {
            let k: i32 = hash(sd * 31 + j) % (j + 1);
            let a: i32 = host::display::state_get(20 + j);
            let b: i32 = host::display::state_get(20 + k);
            host::display::state_set(20 + j, b);
            host::display::state_set(20 + k, a);
            j = j - 1;
        }
        host::display::state_set(1, 0);
        host::display::state_set(2, 0);
        host::display::state_set(3, 0);
        host::display::state_set(4, 0);
        host::display::state_set(5, 0);
        host::display::state_set(8, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(6) == 0;
    host::display::state_set(6, down);
    let mut mmt: i32 = host::display::state_get(3);
    if mmt > 0 {
        mmt = mmt - 1;
        if mmt == 0 {
            let f: i32 = host::display::state_get(1);
            let s: i32 = host::display::state_get(2);
            host::display::state_set(30 + f - 1, 0);
            host::display::state_set(30 + s - 1, 0);
            host::display::state_set(1, 0);
            host::display::state_set(2, 0);
        }
        host::display::state_set(3, mmt);
    }
    if host::display::state_get(8) == 1 {
        if tap {
            host::display::state_set(7, host::display::state_get(7) + 1);
            host::display::state_set(0, 0);
        }
    } else if tap && mmt == 0 {
        let px: i32 = host::display::pointer_x();
        let py: i32 = host::display::pointer_y();
        let c: i32 = (px - 40) / 110;
        let r: i32 = (py - 120) / 140;
        if px >= 40 && c >= 0 && c < 4 && px - 40 - c * 110 < 100 && py >= 120 && r >= 0 && r < 2 && py - 120 - r * 140 < 120 {
            let idx: i32 = r * 4 + c;
            if host::display::state_get(30 + idx) == 0 {
                let first: i32 = host::display::state_get(1);
                if first == 0 {
                    host::display::state_set(1, idx + 1);
                    host::display::state_set(30 + idx, 1);
                } else if first != idx + 1 {
                    host::display::state_set(30 + idx, 1);
                    host::display::state_set(4, host::display::state_get(4) + 1);
                    if host::display::state_get(20 + first - 1) == host::display::state_get(20 + idx) {
                        host::display::state_set(30 + first - 1, 2);
                        host::display::state_set(30 + idx, 2);
                        host::display::state_set(1, 0);
                        let m: i32 = host::display::state_get(5) + 1;
                        host::display::state_set(5, m);
                        if m == 4 { host::display::state_set(8, 1); }
                    } else {
                        host::display::state_set(2, idx + 1);
                        host::display::state_set(3, 45);
                    }
                }
            }
        }
    }
    host::display::clear(0x101018);
    host::display::draw_string(40, 30, "PAIRS", 0xffffff, 3);
    host::display::draw_string(40, 70, "MOVES", 0x808080, 2);
    host::display::draw_number(150, 70, host::display::state_get(4), 0xffffff, 2);
    let mut i2: i32 = 0;
    while i2 < 8 {
        let cx: i32 = 40 + (i2 % 4) * 110;
        let cy: i32 = 120 + (i2 / 4) * 140;
        let st: i32 = host::display::state_get(30 + i2);
        if st == 0 {
            host::display::fill_rect(cx, cy, 100, 120, 0x28304a);
            host::display::fill_rect(cx + 8, cy + 8, 84, 104, 0x1c2338);
        } else {
            let mut bg: i32 = 0x3a4a68;
            if st == 2 { bg = 0x1a5a34; }
            host::display::fill_rect(cx, cy, 100, 120, bg);
            host::display::draw_number(cx + 38, cy + 44, host::display::state_get(20 + i2), 0xffffff, 4);
        }
        i2 = i2 + 1;
    }
    if host::display::state_get(8) == 1 {
        host::display::fill_rect(60, 210, 392, 100, 0x000000);
        host::display::draw_string(90, 230, "ALL MATCHED", 0x00ff88, 3);
        host::display::draw_string(90, 270, "TAP TO SHUFFLE AGAIN", 0x808080, 2);
    }
    host::display::present();
}
